/**
 * Enables the seamless industry strip; the strip itself supports tap and keyboard pause/resume.
 * Motion stops on hover, focus, hidden pages, offscreen content and reduced-motion preference.
 * Duplicate labels are excluded from accessibility navigation; the static layout exposes every label.
 */
function initializeIndustryMarquee() {
    const band = document.getElementById("industryBand");
    if (!band || !("IntersectionObserver" in window)) {
        return;
    }

    const track = band.querySelector(".industry-track");
    const group = band.querySelector(".industry-group");
    const control = band.querySelector(".industry-window");
    const preference = window.matchMedia("(prefers-reduced-motion: reduce)");
    const duplicate = group.cloneNode(true);
    duplicate.setAttribute("aria-hidden", "true");
    duplicate.inert = true;
    track.append(duplicate);

    let manuallyPaused = false;
    let isVisible = false;
    let isHovered = false;
    let isFocused = false;

    /**
     * Synchronizes motion, accessible strip controls and static reduced-motion presentation.
     */
    function updateMotion() {
        band.classList.toggle("marquee-animated", !preference.matches);
        band.classList.toggle("marquee-paused",
            manuallyPaused || !isVisible || isHovered || isFocused || document.hidden || preference.matches);
        if (preference.matches) {
            ["role", "tabindex", "aria-pressed", "aria-label", "title"].forEach(function (attribute) {
                control.removeAttribute(attribute);
            });
        } else {
            control.setAttribute("role", "button");
            control.setAttribute("tabindex", "0");
            control.setAttribute("aria-pressed", String(manuallyPaused));
            control.setAttribute("aria-label",
                `Healthcare, Education, Retail and distribution, Growing businesses. ${manuallyPaused ? "Resume" : "Pause"} industry animation.`);
            control.title = manuallyPaused ? "Tap or press Enter to resume scrolling" : "Tap or press Enter to pause scrolling";
        }
    }

    /**
     * Preserves the visitor's pause choice across hover, focus and viewport changes.
     */
    function togglePause() {
        manuallyPaused = !manuallyPaused;
        updateMotion();
    }

    control.addEventListener("click", function () {
        if (!preference.matches) {
            togglePause();
        }
    });
    control.addEventListener("keydown", function (event) {
        if (!preference.matches && (event.key === "Enter" || event.key === " ")) {
            event.preventDefault();
            togglePause();
        }
    });
    band.addEventListener("pointerenter", function (event) {
        isHovered = event.pointerType !== "touch";
        updateMotion();
    });
    band.addEventListener("pointerleave", function () {
        isHovered = false;
        updateMotion();
    });
    band.addEventListener("focusin", function () {
        isFocused = true;
        updateMotion();
    });
    band.addEventListener("focusout", function (event) {
        isFocused = band.contains(event.relatedTarget);
        updateMotion();
    });
    document.addEventListener("visibilitychange", updateMotion);
    preference.addEventListener("change", updateMotion);
    const observer = new IntersectionObserver(function (entries) {
        isVisible = entries[0].isIntersecting;
        updateMotion();
    });
    observer.observe(band);
    updateMotion();
}

initializeIndustryMarquee();
